{"content":"function isPlainObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

export function readFileLayer(file = {}) {
  if (file === null || typeof file !== 'object' || Array.isArray(file)) throw new TypeError('file must be an object');
  const layer = {};
  if ('network' in file) {
    if (!isPlainObject(file.network)) throw new TypeError('file.network must be an object');
    const network = {};
    if ('endpoint' in file.network) network.endpoint = file.network.endpoint;
    if ('retries' in file.network) network.retries = file.network.retries;
    layer.network = network;
  }
  if ('ui' in file) {
    if (!isPlainObject(file.ui)) throw new TypeError('file.ui must be an object');
    const ui = {};
    if ('theme' in file.ui) ui.theme = file.ui.theme;
    if ('compact' in file.ui) ui.compact = file.ui.compact;
    layer.ui = ui;
  }
  if ('enabled' in file) layer.enabled = file.enabled;
  return layer;
}
